namespace ghidra.app.extension.datatype.finder;







using org.apache.commons.lang3;

using generic.io;
using ghidra.program.model.listing;
using ghidra.util;

/**
 * A package utility class to allow for tests to selectively enable debug output.  This class is
 * used instead of generic logging with the intent that this class will be removed when the bug(s)
 * are fixed.
 * <p>
 * Until {@link #enable()} is called, no data is recorded.  Once enabled, all messages are buffered
 * until a call to {@link #disable(boolean)} is made.
 */
class DtrfDbg {

	private static ByteArrayOutputStream debugBytes;
	private static PrintWriter debugWriter = new NullPrintWriter();

	private static List<string> clientFilters = new();

	private static Map<Function, List<string>> linesByFunction = new();

	private static volatile bool isEnabled = false;

	private DtrfDbg() {
		// static class
	}

	static void enable() {
		debugBytes = new ByteArrayOutputStream();
		debugWriter = new PrintWriter(debugBytes);
		linesByFunction = new();
		isEnabled = true;
	}

	private static void close() {
		isEnabled = false;
		debugWriter.close();
		debugWriter = new NullPrintWriter();
		linesByFunction.clear();
	}

	static void disable(bool write) {

		if (!write) {
			close();
			return;
		}

		Set<Entry<Function, List<string>>> entries = linesByFunction.entrySet();
		foreach (Entry<Function, List<string>> entry in entries) {
			Function function = entry.getKey();
			List<string> lines = entry.getValue();
			debugWriter.println("\n\nFunction Debug: " + function.getName());
			foreach (string line in lines) {
				debugWriter.println(line);
			}
		}

		debugWriter.flush();
		string output = debugBytes.toString();
		if (!StringUtils.isBlank(output)) {
			Msg.debug(typeof(DtrfDbg), "\n\nFinal Debug:\n" + output);
		}

		close();
	}

	/**
	 * Sets filters that will be checked against the {@code toString()} of each client.  The
	 * filtering is a case-sensitive 'contains' check.
	 * @param filters the text
	 */
	static void setClientToStringFilters(params string[] filters) {
		clientFilters.clear();
		clientFilters.addAll(Arrays.asList(filters));
	}

	/**
	 * Stores a message to later be printed. 
	 * 
	 * @param f the function
	 * @param s the message
	 */
	static void println(Function f, string s) {
		if (isEnabled) {
			linesByFunction.computeIfAbsent(f, ff => new()).add(s);
		}
	}

	/**
	 * Stores a message to later be printed, filtering messages based on the 'client' parameter.
	 * 
	 * @param f the function
	 * @param client the client
	 * @param s the message
	 * @see #setClientToStringFilters(String...)
	 */
	static void println(Function f, object client, string s) {
		if (!isEnabled) {
			return;
		}

		if (!passesFilter(client)) {
			return;
		}

		linesByFunction.computeIfAbsent(f, ff => new()).add(s);
	}

	private static bool passesFilter(object client) {
		if (client == null || clientFilters.isEmpty()) {
			return true;
		}

		string asString = client.toString();
		return clientFilters.stream().anyMatch(s => asString.contains(s));
	}
}
